import React, { useState, useRef, useEffect } from "react";
import axios from "axios";
import QRCode from "react-qr-code";
import html2canvas from "html2canvas";
import { Link } from "react-router-dom";
import * as faceapi from "face-api.js";

function Register() {

  const [formData, setFormData] = useState({
    name: "",
    college_name: "",
    phone: "",
    event_id: ""
  });

  const [qrData, setQrData] = useState("");
  const [userId, setUserId] = useState("");
  const [photo, setPhoto] = useState(null);

  const [faceDetected, setFaceDetected] = useState(false);
  const [modelsLoaded, setModelsLoaded] = useState(false);

  const [checkName, setCheckName] = useState("");
  const [checkEvent, setCheckEvent] = useState("");
  const [registeredUser, setRegisteredUser] = useState(null);

  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const idCardRef = useRef(null);
  const streamRef = useRef(null);

  /* =====================
     LOAD FACE MODEL
  ===================== */

  useEffect(() => {

    const loadModels = async () => {

      try {

        await faceapi.nets.tinyFaceDetector.loadFromUri("/models");

        setModelsLoaded(true);

        console.log("Face model loaded");

      } catch (error) {

        console.log("Model error:", error);

      }

    };

    loadModels();

  }, []);

  /* =====================
     INPUT CHANGE
  ===================== */

  const handleChange = (e) => {

    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });

  };

  /* =====================
     REGISTER USER
  ===================== */

  const handleSubmit = async (e) => {

    e.preventDefault();

    try {

      const res = await axios.post(
        "http://localhost:5000/register",
        formData
      );

      setQrData(res.data.qrData);
      setUserId(res.data.userId);

      alert("Registration Successful");

    } catch (error) {

      console.log(error);

      alert("Registration Failed");

    }

  };

  /* =====================
     CHECK ALREADY REGISTERED
  ===================== */

  const checkRegistration = async () => {

    try {

      const res = await axios.post(
        "http://localhost:5000/check-registration",
        {
          name: checkName,
          event_id: checkEvent
        }
      );

      if (res.data.success) {

        setRegisteredUser(res.data.user);

      } else {

        alert("User not registered");

      }

    } catch (error) {

      console.log(error);

    }

  };

  /* =====================
     OPEN CAMERA
  ===================== */

  const openCamera = async () => {

    if (!modelsLoaded) {
      alert("Face model loading...");
      return;
    }

    try {

      const stream = await navigator.mediaDevices.getUserMedia({
        video: true
      });

      videoRef.current.srcObject = stream;

      streamRef.current = stream;

      videoRef.current.onloadedmetadata = () => {

        videoRef.current.play();

        detectFace();

      };

    } catch (error) {

      alert("Camera access denied");

    }

  };

  /* =====================
     FACE DETECTION
  ===================== */

  const detectFace = async () => {

    if (!videoRef.current) return;

    const detections = await faceapi.detectAllFaces(
      videoRef.current,
      new faceapi.TinyFaceDetectorOptions()
    );

    if (detections.length === 1) {

      setFaceDetected(true);

    } else {

      setFaceDetected(false);

    }

    setTimeout(detectFace, 500);

  };

  /* =====================
     CAPTURE PHOTO
  ===================== */

  const capturePhoto = () => {

    const canvas = canvasRef.current;

    const video = videoRef.current;

    const ctx = canvas.getContext("2d");

    canvas.width = video.videoWidth;

    canvas.height = video.videoHeight;

    ctx.drawImage(video, 0, 0);

    const image = canvas.toDataURL("image/png");

    setPhoto(image);

    if (streamRef.current) {

      streamRef.current.getTracks().forEach(track => track.stop());

    }

  };

  /* =====================
     DOWNLOAD ID CARD
  ===================== */

  const downloadCard = () => {

    html2canvas(idCardRef.current).then((canvas) => {

      const link = document.createElement("a");

      link.download = "IDCard.png";

      link.href = canvas.toDataURL();

      link.click();

    });

  };

  return (

    <div style={{ padding: "20px" }}>

      {/* ADMIN BUTTON */}

      <div style={{ position: "absolute", top: "20px", right: "20px" }}>

        <Link to="/admin">
          <button>Admin Login</button>
        </Link>

      </div>

      <h2>College Event Registration</h2>

      {/* REGISTER FORM */}

      <form onSubmit={handleSubmit}>

        <input
          name="name"
          placeholder="Name"
          onChange={handleChange}
          required
        />

        <br /><br />

        <input
          name="college_name"
          placeholder="College Name"
          onChange={handleChange}
          required
        />

        <br /><br />

        <input
          name="phone"
          placeholder="Phone"
          onChange={handleChange}
          required
        />

        <br /><br />

        <select name="event_id" onChange={handleChange} required>

          <option value="">Select Event</option>
          <option value="1">Technical Event</option>
          <option value="2">24 Hackathon</option>
          <option value="3"></option>
          <option value="4">Cultural Event</option>
          <option value="5">Cultural Event</option>
          <option value="6">Cultural Event</option>
          <option value="7">Cultural Event</option>
          <option value="2">Cultural Event</option>
          <option value="2">Cultural Event</option>
          <option value="2">Cultural Event</option>
          <option value="2">Cultural Event</option>
          <option value="2">Cultural Event</option>

        </select>

        <br /><br />

        <button type="submit">
          Register
        </button>

      </form>

      <hr />

      {/* ALREADY REGISTERED */}

      <h3>Already Registered?</h3>

      <input
        placeholder="Enter Name"
        onChange={(e) => setCheckName(e.target.value)}
      />

      <br /><br />

      <input
        placeholder="Enter Event No"
        onChange={(e) => setCheckEvent(e.target.value)}
      />

      <br /><br />

      <button onClick={checkRegistration}>
        Check Registration
      </button>

      {registeredUser && (

        <div style={{ marginTop: "20px", border: "1px solid black", padding: "10px" }}>

          <h4>User Found</h4>

          <p>Name: {registeredUser.name}</p>
          <p>College: {registeredUser.college_name}</p>
          <p>Phone: {registeredUser.phone}</p>
          <p>Event: {registeredUser.event_id}</p>

        </div>

      )}

      {/* QR + CAMERA */}

      {qrData && (

        <div>

          <h3>Your QR Code</h3>

          <QRCode value={qrData} size={120} />

          <h3>Take Photo</h3>

          <button onClick={openCamera}>
            Open Camera
          </button>

          <br /><br />

          <video
            ref={videoRef}
            autoPlay
            playsInline
            width="300"
            height="200"
            style={{ border: "2px solid black" }}
          />

          <br />

          {faceDetected ?
            <p style={{ color: "green" }}>1 Face Detected</p> :
            <p style={{ color: "red" }}>No Face / Multiple Faces</p>
          }

          <button
            onClick={capturePhoto}
            disabled={!faceDetected}
          >
            Capture Photo
          </button>

          <canvas
            ref={canvasRef}
            style={{ display: "none" }}
          />

        </div>

      )}

      {/* ID CARD */}

      {photo && (

        <div>

          <div
            ref={idCardRef}
            style={{
              border: "2px solid black",
              width: "300px",
              padding: "10px",
              marginTop: "20px"
            }}
          >

            <h3>College Event ID Card</h3>

            <p>Name: {formData.name}</p>

            <p>User ID: {userId}</p>

            <p>Event: {formData.event_id}</p>

            <QRCode value={qrData} size={100} />

            <br /><br />

            <img src={photo} alt="user" width="120" />

          </div>

          <br />

          <button onClick={downloadCard}>
            Download ID Card
          </button>

        </div>

      )}

    </div>

  );

}

export default Register;
